class Solution:
    def maxTrailingZeros(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def cnt(x, p):
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            return c

        F2 = [[cnt(v, 2) for v in row] for row in grid]
        F5 = [[cnt(v, 5) for v in row] for row in grid]
        ans = 0
        for i in range(m):
            for j in range(n):
                left2, left5 = sum(F2[i][:j]), sum(F5[i][:j])
                right2, right5 = sum(F2[i][j+1:]), sum(F5[i][j+1:])
                up2 = sum(F2[r][j] for r in range(i))
                up5 = sum(F5[r][j] for r in range(i))
                down2 = sum(F2[r][j] for r in range(i+1, m))
                down5 = sum(F5[r][j] for r in range(i+1, m))
                h2 = [left2, right2, 0]; h5 = [left5, right5, 0]
                v2 = [up2, down2, 0]; v5 = [up5, down5, 0]
                for a in range(3):
                    for b in range(3):
                        ans = max(ans, min(F2[i][j] + h2[a] + v2[b], F5[i][j] + h5[a] + v5[b]))
        return ans

